"""Micro-benchmark for build_ambiguous_under_inner_keys() — the sage
reference implementation that attack_crypto.c is ported from. Mirrors
the C bench (bench_attack_crypto.c) so the two can be compared
side-by-side. Reports mean / p50 / p99 wall-time per call across the
same plaintext sizes."""


# This file was *autogenerated* from the file attack/hook/bench_sage.sage
from sage.all_cmdline import *   # import sage library

_sage_const_1 = Integer(1); _sage_const_0xff = Integer(0xff); _sage_const_32 = Integer(32); _sage_const_0x10 = Integer(0x10); _sage_const_12 = Integer(12); _sage_const_4 = Integer(4); _sage_const_0xdeadbeef = Integer(0xdeadbeef); _sage_const_7 = Integer(7); _sage_const_0xffff = Integer(0xffff); _sage_const_0 = Integer(0); _sage_const_1000p0 = RealNumber('1000.0'); _sage_const_2 = Integer(2); _sage_const_99 = Integer(99); _sage_const_100 = Integer(100); _sage_const_1e6 = RealNumber('1e6'); _sage_const_200 = Integer(200); _sage_const_16 = Integer(16); _sage_const_80 = Integer(80); _sage_const_256 = Integer(256); _sage_const_50 = Integer(50); _sage_const_1280 = Integer(1280); _sage_const_20 = Integer(20)
from binascii import unhexlify
import statistics
import time

load('attack/crypto/util.sage')
load('attack/crypto/gcm.sage')
load('attack/crypto/srtp_kdf.sage')
load('attack/crypto/test_packet_ambiguous.sage')


def bench_one(label, plaintext_len, iters):
    K_OLD = bytes(((i + _sage_const_1 ) & _sage_const_0xff ) for i in range(_sage_const_32 ))
    K_NEW = bytes(((_sage_const_0xff  - i) & _sage_const_0xff ) for i in range(_sage_const_32 ))
    SALT  = bytes(((_sage_const_0x10  + i) & _sage_const_0xff ) for i in range(_sage_const_12 ))
    AAD   = bytes.fromhex("80600042deadbeefcafebabe")
    PT    = bytes((i & _sage_const_0xff ) for i in range(plaintext_len))

    # Warmup
    for i in range(_sage_const_4 ):
        build_ambiguous_under_inner_keys(
            PT, K_OLD, K_NEW, SALT, _sage_const_0xdeadbeef , _sage_const_7 , i & _sage_const_0xffff ,
            adjustment_block_offset=_sage_const_0 , aad=AAD,
        )

    samples = []
    for i in range(iters):
        t0 = time.perf_counter_ns()
        build_ambiguous_under_inner_keys(
            PT, K_OLD, K_NEW, SALT, _sage_const_0xdeadbeef , _sage_const_7 , i & _sage_const_0xffff ,
            adjustment_block_offset=_sage_const_0 , aad=AAD,
        )
        t1 = time.perf_counter_ns()
        samples.append(t1 - t0)

    samples.sort()
    mean_us = statistics.mean(samples) / _sage_const_1000p0 
    p50_us  = samples[len(samples) // _sage_const_2 ] / _sage_const_1000p0 
    p99_us  = samples[(len(samples) * _sage_const_99 ) // _sage_const_100 ] / _sage_const_1000p0 
    pmin_us = samples[_sage_const_0 ] / _sage_const_1000p0 
    print(f"  {label:26s}  iters={iters}  mean={mean_us:8.1f} us  "
          f"p50={p50_us:8.1f} us  p99={p99_us:8.1f} us  min={pmin_us:8.1f} us  "
          f"(throughput≈{_sage_const_1e6 /mean_us:8.1f} calls/s)")


def bench_derive(iters):
    K_OLD = bytes(((i + _sage_const_1 ) & _sage_const_0xff ) for i in range(_sage_const_32 ))
    K_NEW = bytes(((_sage_const_0xff  - i) & _sage_const_0xff ) for i in range(_sage_const_32 ))
    SALT  = bytes(((_sage_const_0x10  + i) & _sage_const_0xff ) for i in range(_sage_const_12 ))

    # Warmup
    for _ in range(_sage_const_4 ):
        derive_inner_keys(K_OLD, SALT)
        derive_inner_keys(K_NEW, SALT)

    samples = []
    for _ in range(iters):
        t0 = time.perf_counter_ns()
        derive_inner_keys(K_OLD, SALT)
        derive_inner_keys(K_NEW, SALT)
        t1 = time.perf_counter_ns()
        samples.append(t1 - t0)
    samples.sort()
    mean_us = statistics.mean(samples) / _sage_const_1000p0 
    p50_us  = samples[len(samples) // _sage_const_2 ] / _sage_const_1000p0 
    p99_us  = samples[(len(samples) * _sage_const_99 ) // _sage_const_100 ] / _sage_const_1000p0 
    print(f"  {'derive_inner_keys (×2)':26s}  iters={iters}  "
          f"mean={mean_us:8.1f} us  p50={p50_us:8.1f} us  p99={p99_us:8.1f} us")


def main():
    print("[*] sage implementation (attack/crypto/test_packet_ambiguous.sage)")
